async getDetailsById(id: number) {
  const tool = await this.repository.getById(id);
  if (!tool)
    throw new NotFoundException({...});
  const total = await this.usageLogs.totalSession(id);
  const avg_session_minutes = await this.usageLogs.averageUsage(id);
  return {
    ...tool, monthly_cost: Number(tool.monthly_cost.toDecimalPlaces(2)), 
    usage_metrics: {
      last_30_days: { total_session: total, avg_session_minutes },
    },
  };
}

