async countSessions(toolId: number) {
  const date = await this.getSessionDate(toolId);
  return await prisma.usage_logs.count({
    where: {
      tools: { id: toolId },
      session_date: {
        gte: new Date(new Date().setFullYear(date.getFullYear(), date.getMonth(), 1)),
        lte: new Date(new Date().setFullYear(date.getFullYear(), date.getMonth(), 30)),
      },
    },
  });
}

async averageUsageMinutes(toolId: number) {
  const date = await this.getSessionDate(toolId);
  return await prisma.usage_logs.aggregate({
    _avg: { usage_minutes: true },
    where: {
      tool_id: toolId,
      session_date: {
        gte: new Date(new Date().setFullYear(date.getFullYear(), date.getMonth(), 1)),
        lte: new Date(new Date().setFullYear(date.getFullYear(), date.getMonth(), 30)),
      },
    },
  });
}

